-- 24 September 2026 daily current-affairs desk.
-- Original revision briefs based on primary official releases issued from 21 to 23 September.

insert into public.current_affairs_briefs (
  slug, published_on, title, summary, why_it_matters, background,
  source_title, source_url, source_publisher, source_published_on,
  prelims_takeaways, quick_check, visual_data, status, reviewed_at
) values
(
  $$2026-09-24-india-new-zealand-fta-entry-into-force$$, $$2026-09-24$$,
  $$India-New Zealand FTA will enter into force on 20 October 2026$$,
  $$India and New Zealand announced that their Free Trade Agreement will enter into force on 20 October 2026, after both sides completed their internal processes. The agreement was signed in New Delhi on 27 April 2026.$$,
  $$This is an international-trade milestone. For prelims, distinguish signing an agreement from its entry into force: an FTA normally begins to apply only after the agreed domestic procedures are completed.$$,
  $$The official release says New Zealand will provide zero duty on all Indian exports from day one. It also identifies the India-New Zealand Strategic Partnership Roadmap to 2030 as the wider cooperation framework and notes a goal of doubling two-way goods and services trade to NZ$7 billion by 2030.$$,
  $$India-New Zealand FTA to Enter into Force from 20 October 2026$$,
  $$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2313143&lang=1&reg=1$$,
  $$Ministry of Commerce and Industry / Press Information Bureau$$, $$2026-09-21$$,
  $$["The India-New Zealand FTA is scheduled to enter into force on 20 October 2026.","It was signed on 27 April 2026 at Bharat Mandapam in New Delhi.","The release says New Zealand will offer zero duty on 100% of Indian exports from day one.","Entry into force follows completion of internal processes; it is different from the date of signing."]$$::jsonb,
  $$[{"question":"When will the India-New Zealand FTA enter into force?","answer":"20 October 2026."},{"question":"Is signing an FTA the same as bringing it into force?","answer":"No. Entry into force follows the agreed domestic and bilateral procedures."}]$$::jsonb,
  $${"title":"From treaty signature to trade operation","steps":["Countries negotiate and sign an agreement.","Each side completes its required internal process.","They announce an entry-into-force date.","Tariff preferences and other agreed obligations then become operational."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-09-24-udan-challenge-mode-aerodromes$$, $$2026-09-24$$,
  $$Modified UDAN opens Challenge Mode for States and UTs to nominate aerodromes$$,
  $$The Ministry of Civil Aviation launched the Challenge Mode portal for aerodrome development in the next phase of UDAN and signed 21 MoUs with States and Union Territories. The scheme document for the next route-bidding round was also released.$$,
  $$This combines a regional-connectivity scheme with cooperative implementation. Challenge Mode allows States and UTs to propose airstrips and helipads for assessment; it does not mean every nominated site automatically becomes an operational airport.$$,
  $$UDAN is Ude Desh ka Aam Nagrik, the regional-connectivity framework. The release identifies affordability, sustainable operations, a transparent Challenge Mode framework and indigenous manufacturing as pillars of Modified UDAN. Airports Authority of India is the implementing agency named in the MoUs.$$,
  $$Civil Aviation Minister launches Challenge Mode for Aerodrome Development$$,
  $$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2313612&lang=2&reg=48$$,
  $$Ministry of Civil Aviation / Press Information Bureau$$, $$2026-09-22$$,
  $$["UDAN stands for Ude Desh ka Aam Nagrik.","The Challenge Mode portal enables States and UTs to nominate airstrips and helipads for development consideration.","Twenty-one MoUs were signed with States and UTs for the next phase of UDAN.","AAI is identified as the implementing agency under the UDAN scheme."]$$::jsonb,
  $$[{"question":"What can a State or UT nominate through UDAN Challenge Mode?","answer":"An airstrip or helipad for development consideration."},{"question":"Which agency is named as UDAN's implementing agency in the release?","answer":"Airports Authority of India."}]$$::jsonb,
  $${"title":"UDAN Challenge Mode pathway","steps":["A State or UT identifies a potential aviation asset.","It nominates the site through the portal.","The Centre, State or UT and AAI coordinate development planning.","A later route-bidding process seeks airline operators for identified routes."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-09-24-nhai-high-speed-corridor-guidelines$$, $$2026-09-24$$,
  $$NHAI issues a uniform design framework for access-controlled high-speed highways$$,
  $$NHAI released guidelines for planning and designing access-controlled high-speed National Highways other than expressways. They apply to upcoming four- and six-lane greenfield and brownfield high-speed corridors.$$,
  $$The update is relevant to infrastructure planning, road safety and logistics. It sets a common Detailed Project Report framework; it should not be confused with a single highway project approval or a rule that applies only to expressways.$$,
  $$The guidelines are linked to the long-term objective of 50,000 km of access-controlled high-speed corridors. They prescribe traffic-based lane and right-of-way configurations, ramps at major intersections, advance exit and entry information, and a one-metre boundary wall along the outer corridor edge to strengthen access control.$$,
  $$NHAI Introduces New Guidelines for Design and Development of Access-Controlled High-Speed National Highways$$,
  $$https://www.pib.gov.in/PressReleaseIframePage.aspx?PRID=2313032&lang=2&reg=48$$,
  $$Ministry of Road Transport and Highways / Press Information Bureau$$, $$2026-09-21$$,
  $$["The guidelines cover high-speed access-controlled National Highways other than expressways.","They apply to upcoming four- and six-lane greenfield and brownfield corridors.","The release links the policy objective to 50,000 km of access-controlled high-speed corridors.","The framework includes traffic-based configuration, interchanges, advance exit information and boundary-wall provisions."]$$::jsonb,
  $$[{"question":"Do the new NHAI guidelines apply only to expressways?","answer":"No. They cover access-controlled high-speed National Highways other than expressways."},{"question":"What planning document do the guidelines seek to standardise?","answer":"The Detailed Project Report for high-speed corridors."}]$$::jsonb,
  $${"title":"Uniform high-speed corridor design","steps":["Traffic assessment determines the needed corridor configuration.","The DPR applies common technical and safety standards.","Interchanges manage major crossings and traffic generators.","Access control and advance information support safer, uninterrupted movement."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-09-24-nhai-ssnnl-gujarat-approvals$$, $$2026-09-24$$,
  $$NHAI and SSNNL create a time-bound approvals framework in Gujarat$$,
  $$National Highways Authority of India and Sardar Sarovar Narmada Nigam Limited signed an MoU to simplify approvals for national-highway, canal and pipeline crossings in Gujarat. The framework is intended to coordinate infrastructure work that crosses the two agencies' networks.$$,
  $$This is a useful example of inter-agency infrastructure governance. The MoU creates an approval mechanism; it is not itself sanction for every highway, canal or pipeline project that may use the framework.$$,
  $$SSNNL is the Gujarat government undertaking associated with the Sardar Sarovar Project. The arrangement is designed to facilitate faster approvals and avoid avoidable delays when highway and irrigation infrastructure interact in the State.$$,
  $$NHAI Signs MoU with SSNNL to Simplify Approval Framework for National Highway and Irrigation Infrastructure Projects in Gujarat$$,
  $$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2313520&lang=1&reg=3$$,
  $$Ministry of Road Transport and Highways / Press Information Bureau$$, $$2026-09-22$$,
  $$["The MoU is between NHAI and Sardar Sarovar Narmada Nigam Limited.","It concerns approval processes for highway, canal and pipeline crossings in Gujarat.","The stated aim is a simplified and time-bound framework for approvals.","The agreement supports coordination between road and irrigation infrastructure agencies."]$$::jsonb,
  $$[{"question":"Which Gujarat undertaking signed the MoU with NHAI?","answer":"Sardar Sarovar Narmada Nigam Limited (SSNNL)."},{"question":"Does the MoU automatically approve every individual project?","answer":"No. It establishes a coordination and approval framework."}]$$::jsonb,
  $${"title":"Crossing-infrastructure approvals","steps":["A road or irrigation project needs to cross another agency's asset.","NHAI and SSNNL use a defined coordination framework.","The relevant technical and administrative approvals are processed.","The project can proceed with fewer inter-agency delays once approvals are in place."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-09-24-t72-t90-auxiliary-power-units$$, $$2026-09-24$$,
  $$MoD contracts indigenous auxiliary power units for T-72 and T-90 tanks$$,
  $$The Ministry of Defence signed a ₹586 crore contract with Accurate Industrial Controls Private Limited to procure auxiliary power units for T-72 and T-90 tanks. The procurement is presented as a Make-II and indigenisation step for armoured platforms.$$,
  $$This is a defence-indigenisation item. An auxiliary power unit supports onboard electrical needs; it is a subsystem procurement, not the acquisition of additional T-72 or T-90 tanks.$$,
  $$According to the release, the APUs provide alternate electrical power for the fire-control system, firing circuit, gun-stabilisation system and other ancillary systems. The intended effect is stronger operational readiness, reliability and sustainability for Indian Army mechanised formations.$$,
  $$MoD inks Rs 586 crore contract to procure Auxiliary Power Units for T-72 and T-90 Tanks$$,
  $$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2313016&lang=2&reg=48$$,
  $$Ministry of Defence / Press Information Bureau$$, $$2026-09-21$$,
  $$["The contract value is ₹586 crore.","It covers auxiliary power units for T-72 and T-90 tanks.","An APU supplies alternate electrical power to key tank systems.","The release describes the procurement as an indigenisation step under Make-II."]$$::jsonb,
  $$[{"question":"What does an auxiliary power unit do in the tanks described?","answer":"It provides alternate electrical power for systems such as fire control and gun stabilisation."},{"question":"Is this a contract to buy new tanks?","answer":"No. It is for a critical subsystem for existing tank platforms."}]$$::jsonb,
  $${"title":"Indigenising a tank subsystem","steps":["A tank needs reliable electrical supply for critical onboard systems.","An APU provides an alternate power source.","An Indian supplier produces the subsystem under the procurement contract.","Induction supports readiness and sustainment of mechanised formations."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-09-24-sat-saaw-bdl-contract$$, $$2026-09-24$$,
  $$MoD orders 160 SAT-SAAW precision glide weapons for the Indian Air Force$$,
  $$The Ministry of Defence contracted Bharat Dynamics Limited for 160 Satellite Smart Anti Airfield Weapons and associated equipment for the Indian Air Force at a cost of ₹810.79 crore. The procurement is under the Buy (Indian-IDDM) category.$$,
  $$This is a defence-acquisition and indigenisation item. SAT-SAAW is an air-to-ground precision-guided glide weapon, not a satellite or a surface-to-air missile system.$$,
  $$The system is designed and developed by DRDO and can be launched from Jaguar, Hawk and Su-30 MKI platforms. The release states that it has a 60% indigenous content and is intended for long stand-off attacks against enemy airfields; deliveries are scheduled across 2027–28 and 2028–29.$$,
  $$Major boost to Aatmanirbhar Bharat: MoD signs Rs 811 crore contract with BDL for 160 Satellite Smart Anti Airfield Weapons for IAF$$,
  $$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2313942&lang=1&reg=3$$,
  $$Ministry of Defence / Press Information Bureau$$, $$2026-09-23$$,
  $$["The contract covers 160 SAT-SAAW weapons and associated equipment for the IAF.","Its value is ₹810.79 crore and the category is Buy (Indian-IDDM).","SAT-SAAW is an air-to-ground precision-guided glide weapon designed and developed by DRDO.","The release names Jaguar, Hawk and Su-30 MKI as launch platforms and states indigenous content of 60%."]$$::jsonb,
  $$[{"question":"Which organisation designed and developed SAT-SAAW?","answer":"DRDO."},{"question":"Is SAT-SAAW a surface-to-air missile?","answer":"No. It is an air-to-ground precision-guided glide weapon."}]$$::jsonb,
  $${"title":"SAT-SAAW acquisition chain","steps":["DRDO designs the precision glide weapon.","BDL supplies the contracted weapons and equipment.","IAF aircraft carry the weapon for stand-off operations.","Indigenous subsystems support the Indian-IDDM procurement category."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-09-24-slinex-26-concludes$$, $$2026-09-24$$,
  $$SLINEX-26 strengthens India-Sri Lanka maritime interoperability$$,
  $$The 13th India-Sri Lanka bilateral maritime exercise, SLINEX-26, concluded at Visakhapatnam on 21 September after being conducted from 17 to 21 September. It involved both harbour and sea phases.$$,
  $$Bilateral exercises are a recurring defence and neighbourhood-policy theme. This brief tests the participating countries and the purpose—professional exchange and interoperability—rather than treating every operational drill as a treaty or a new naval command.$$,
  $$The sea phase included coordinated manoeuvres, air operations, night replenishment at sea and special-forces drills such as Visit, Board, Search and Seizure. The Ministry of Defence links the exercise to maritime cooperation in the Indian Ocean Region, MAHASAGAR and the Neighbourhood First policy.$$,
  $$India-Sri Lanka Bilateral Maritime Exercise SLINEX-26 Concluded at Visakhapatnam$$,
  $$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2313929&lang=2&reg=48$$,
  $$Ministry of Defence / Press Information Bureau$$, $$2026-09-23$$,
  $$["SLINEX-26 was the 13th edition of the India-Sri Lanka bilateral maritime exercise.","It was conducted from 17 to 21 September 2026 and concluded at Visakhapatnam.","The exercise had harbour and sea phases.","Sea-phase activities included coordinated manoeuvres, air operations, night replenishment and VBSS drills."]$$::jsonb,
  $$[{"question":"Which two countries participate in SLINEX?","answer":"India and Sri Lanka."},{"question":"Where did SLINEX-26 conclude?","answer":"Visakhapatnam."}]$$::jsonb,
  $${"title":"Bilateral naval-exercise structure","steps":["The navies meet for professional interaction in harbour.","They conduct coordinated activities at sea.","Common drills build familiarity with procedures and communication.","Interoperability supports maritime cooperation in the Indian Ocean Region."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-09-24-kavach-4-scr-commissioning$$, $$2026-09-24$$,
  $$Kavach 4.0 is commissioned for the first time on South Central Railway$$,
  $$Indian Railways commissioned Kavach Version 4.0 over 108 route kilometres on the Malkajgiri-Kamareddi section of Hyderabad Division, upgrading the section from Version 3.2. This is the first 4.0 commissioning on South Central Railway.$$,
  $$Kavach is India's indigenous Automatic Train Protection system. The key exam distinction is between commissioning a deployed safety system and merely approving, testing or planning it for future use.$$,
  $$Kavach assists the loco pilot with speed compliance and can apply brakes when required. The release identifies improved location accuracy, better signal-aspect information in bigger yards, station-to-station optical-fibre connectivity and direct electronic-interlocking interface as Version 4.0 upgrades. It also states that the system requires SIL-4 safety certification.$$,
  $$Indian Railways Commissions KAVACH 4.0 for the First Time on South Central Railway$$,
  $$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2313758&lang=1&reg=3$$,
  $$Ministry of Railways / Press Information Bureau$$, $$2026-09-23$$,
  $$["Kavach 4.0 was commissioned over 108 route kilometres on the Malkajgiri-Kamareddi section.","The section is in Hyderabad Division of South Central Railway.","Kavach is an indigenous Automatic Train Protection system.","Version 4.0 adds location accuracy, improved yard signal information, OFC connectivity and electronic-interlocking interface."]$$::jsonb,
  $$[{"question":"On which railway zone was Kavach 4.0 first commissioned in this release?","answer":"South Central Railway."},{"question":"What is Kavach's core system type?","answer":"An Automatic Train Protection system."}]$$::jsonb,
  $${"title":"How Kavach supports rail safety","steps":["Trackside, station and locomotive components provide train-protection information.","The system monitors safety-critical operating conditions.","It assists the loco pilot with speed compliance.","It can automatically apply brakes when required to reduce collision and SPAD risk."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-09-24-domestic-tourism-expenditure-survey$$, $$2026-09-24$$,
  $$NSO releases Domestic Tourism Expenditure Survey findings from the 80th NSS round$$,
  $$The Ministry of Statistics and Programme Implementation released findings from the Domestic Tourism Expenditure Survey conducted from July 2025 to June 2026 as part of the 80th National Sample Survey round. The survey records domestic overnight and same-day trip patterns and expenditure.$$,
  $$This is an official-statistics item for economy, tourism and survey-method questions. It reports household travel behaviour and spending; it is not an administrative count of tourist arrivals or a tourism-policy announcement.$$,
  $$The report says pilgrimage and religious travel accounted for around 48 of every 100 relevant overnight trips in the preceding 365 days, while business trips had the highest average household expenditure among overnight trips completed in the last 30 days at ₹5,949. It covers duration, transport, stay and trip expenses.$$,
  $$Press Note on Domestic Tourism Expenditure Survey July 2025 to June 2026$$,
  $$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2313894&lang=2&reg=48$$,
  $$Ministry of Statistics and Programme Implementation / Press Information Bureau$$, $$2026-09-23$$,
  $$["The Domestic Tourism Expenditure Survey was conducted from July 2025 to June 2026 as part of NSS 80th round.","It covers domestic overnight trips as well as same-day trips and associated expenditure.","The release reports pilgrimage and religious purpose for around 48 of every 100 specified overnight trips in the prior 365 days.","Business trips had the highest average household spending among overnight trips completed in the last 30 days, at ₹5,949."]$$::jsonb,
  $$[{"question":"Which body conducted the Domestic Tourism Expenditure Survey?","answer":"The National Statistics Office."},{"question":"Does the survey only record overnight trips?","answer":"No. It also captures information on same-day trips and spending."}]$$::jsonb,
  $${"title":"What the tourism-expenditure survey measures","steps":["Households report domestic trips within defined recall periods.","The survey records trip purpose, duration, transport and stay.","It records expenditure for overnight and same-day travel.","NSO compiles results into official tourism-behaviour statistics."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-09-24-ubifly-eplane-rdi-support$$, $$2026-09-24$$,
  $$TDB approves ₹285 crore RDI support for an indigenous ePlane project$$,
  $$The Technology Development Board under the Department of Science and Technology approved ₹285 crore in support to Ubifly Technologies for the e200X advanced-air-mobility project. The support is from the Research, Development and Innovation Fund and is structured through optionally convertible debentures.$$,
  $$This is a science-and-technology financing development. The project aims to mature an electric aircraft technology from Technology Readiness Level 6 to 9; it does not mean a commercial passenger service has begun.$$,
  $$The release gives the total approved project cost as ₹570 crore. It describes the e200X as a three-seat, zero-emission advanced-air-mobility aircraft and says development involves technology maturation, testing, validation and scale-up before operational demonstration.$$,
  $$TDB-DST backs India's next-generation air mobility ambitions with ₹285 crore RDI support to Ubifly Technologies$$,
  $$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2313853&lang=1&reg=3$$,
  $$Department of Science and Technology / Press Information Bureau$$, $$2026-09-23$$,
  $$["Technology Development Board approved ₹285 crore support for the e200X project.","The support is from the Research, Development and Innovation Fund and is structured through optionally convertible debentures.","The project is intended to progress from TRL 6 to TRL 9.","The release gives the total approved project cost as ₹570 crore and describes e200X as a three-seat zero-emission aircraft."]$$::jsonb,
  $$[{"question":"Which body approved the RDI support for the e200X project?","answer":"The Technology Development Board under the Department of Science and Technology."},{"question":"Does movement from TRL 6 to TRL 9 mean commercial service has already started?","answer":"No. It covers maturation, testing, validation and scale-up toward operational demonstration."}]$$::jsonb,
  $${"title":"From advanced prototype to demonstration","steps":["A deep-tech project reaches an advanced prototype stage.","RDI support finances maturation, testing and validation.","The technology advances through higher readiness levels.","An operationally demonstrated system can then be considered for commercialisation."]}$$::jsonb,
  $$published$$, now()
)
on conflict (slug) do update set
  title = excluded.title,
